import sys

for line in sys.stdin:
    path = line.strip()
    with open(path, 'rb') as f:
        raw = f.read()
    try:
        decompressed = zlib.decompress(raw)
    except Exception as e:
        print(f'ERR: {path} {e}')
        continue
    header, _, content = decompressed.partition(b'\x00')
    if b'commit' in header:
        print(f'---COMMIT--- {path}')
        print(content.decode(errors='replace')[:1000])
        print('---END---')
    elif b'blob' in header:
        text = content.decode(errors='replace')
        print(f'---BLOB--- {path}')
        if ("secret" in text.lower() or "flag" in text.lower() or "key" in text.lower() or "password" in text.lower()):
            print('[!!] POSSIBLE SECRET FOUND')
        for i, line in enumerate(text.splitlines()):
            if i > 49:
                break
            print(line)
        print('---END---')
    else:
        print(f'---OTHER--- {path}')
        print(decompressed[:100])
        print('---END---')

