import os
import zlib

keywords = [b'flag', b'secret']
summary = []
dir_path = '/home/ctfplayer/ctf_files/sourcery_challenge/.git/objects/'

def process_object(path):
    with open(path, 'rb') as f:
        raw = f.read()
    try:
        decompressed = zlib.decompress(raw)
    except Exception:
        return None
    lines = decompressed.split(b'\n')
    json_entry = {'name': path, 'preview': [], 'keywords': [], 'is_commit': False, 'commit_msg': ''}
    if decompressed.startswith(b'commit'):
        json_entry['is_commit'] = True
        idx = decompressed.find(b'\n\n')
        if idx > 0:
            commit_msg = decompressed[idx+2:idx+2+200].decode(errors='ignore').strip()
            json_entry['commit_msg'] = commit_msg
    # Check for keywords
    for k in keywords:
        if k in decompressed:
            context = decompressed.split(k, 1)
            prefix = context[0][-40:] if len(context[0])>40 else context[0]
            suffix = context[1][:40] if len(context)>1 else b''
            json_entry['keywords'].append(f"...{prefix.decode(errors='ignore')}[{k.decode()}]{suffix.decode(errors='ignore')}...")
    # Save preview if text
    if all(chr(b) in '\n\r\t\x08' or 32<=b<127 for b in decompressed[:100]):
        preview = b'\n'.join(lines[:50]).decode(errors='ignore')
        json_entry['preview'] = preview
    return json_entry

for root, dirs, files in os.walk(dir_path):
    for file in files:
        if file in ('.', '..'):
            continue
        obj_path = os.path.join(root, file)
        # skip pack/info
        if '/pack/' in obj_path or '/info/' in obj_path:
            continue
        result = process_object(obj_path)
        if result and (result['is_commit'] or result['keywords'] or result['preview']):
            summary.append(result)

for item in summary:
    print(f"\nObject: {item['name']}")
    if item['is_commit']:
        print(f"Commit message: {item['commit_msg']}")
    if item['keywords']:
        for k in item['keywords']:
            print(f"Keyword: {k}")
    if item['preview']:
        print("Preview:\n"+item['preview'])

