import os
import zlib
import re
from pathlib import Path

OBJ_DIR = '/home/ctfplayer/ctf_files/sourcery_challenge/.git/objects/'

results = []
keywords = re.compile(rb'(flag|secret|key)', re.IGNORECASE)

for root, dirs, files in os.walk(OBJ_DIR):
    for file in files:
        if file in ('pack', 'info'):
            continue
        path = os.path.join(root, file)
        sha = Path(root).name + file
        try:
            with open(path, 'rb') as f:
                raw = f.read()
            decomp = zlib.decompress(raw)
            if decomp.startswith(b'commit'):
                # Find commit message
                try:
                    msg = decomp.split(b'\n\n',1)[1].decode(errors='ignore')
                except Exception:
                    msg = 'Could not decode commit message'
                results.append({'sha': sha, 'type': 'commit', 'context': msg.strip()[:300]})
            elif decomp.startswith(b'blob'):
                content = decomp.split(b'\0',1)[1]
                found = keywords.search(content)
                if found:
                    # Save lines with/near keyword in context
                    lines = content.decode(errors='ignore').split('\n')
                    contexts = []
                    for i,l in enumerate(lines):
                        if keywords.search(l.encode()):
                            begin = max(0, i-3)
                            end = min(len(lines), i+4)
                            contexts.extend(lines[begin:end])
                    ctx = '\n'.join(contexts)
                    results.append({'sha': sha, 'type': 'blob', 'context': ctx[:500]})
                else:
                    preview = '\n'.join(content.decode(errors='ignore').split('\n')[:50])
                    results.append({'sha': sha, 'type': 'blob', 'context': preview.strip()})
            else:
                if keywords.search(decomp):
                    idx = decomp.lower().index(keywords.search(decomp).group(0))
                    context = decomp[max(0,idx-30):idx+100].decode(errors='ignore')
                    results.append({'sha':sha, 'type': 'other', 'context': context.strip()})
        except Exception as e:
            results.append({'sha': sha, 'type': 'error', 'context': str(e)})

with open('/home/ctfplayer/objects_decompressed_summary.txt','w') as f:
    for r in results:
        f.write(f"SHA: {r['sha']} TYPE: {r['type']}\nContext:\n{r['context']}\n{'-'*24}\n")

