import os
import zlib
import re

OBJ_LIST = '/tmp/object_files.txt'
MAX_LINES = 50
INTEREST_WORDS = [b'flag', b'secret', b'key', b'password', b'token']

with open(OBJ_LIST) as f:
    files = [l.strip() for l in f if l.strip()]

interesting_objects = []
all_summaries = []

def check_interest(data):
    context = []
    data_lower = data.lower()
    for word in INTEREST_WORDS:
        idx = data_lower.find(word)
        if idx >= 0:
            snippet = data[max(0, idx-40):idx+60]
            context.append(snippet)
    return context

for obj_path in files:
    try:
        with open(obj_path, 'rb') as f:
            raw = f.read()
        decompressed = zlib.decompress(raw)
        summary = {'object': obj_path, 'type': None, 'info': None, 'interest': []}
        if decompressed.startswith(b'commit'):
            summary['type'] = 'commit'
            msg = decompressed.split(b'\0',1)[-1]
            msg_str = msg.decode(errors='replace')
            lines = msg_str.splitlines()
            for l in lines:
                if l.strip():
                    summary['info'] = l.strip()
                    break
        elif decompressed.startswith(b'blob'):
            summary['type'] = 'blob'
            content = decompressed.split(b'\0',1)[-1]
            try:
                text = content.decode(errors='replace')
                lines = text.splitlines()[:MAX_LINES]
                summary['info'] = '\n'.join(lines)
            except:
                summary['info'] = '[non-text or binary data]'
            interest = check_interest(content)
            if interest:
                summary['interest'] = [i.decode(errors='replace') for i in interest]
                interesting_objects.append(obj_path)
        else:
            summary['type'] = 'unknown'
            summary['info'] = ''
        summary['object_sha'] = os.path.basename(os.path.dirname(obj_path)) + os.path.basename(obj_path)
        all_summaries.append(summary)
    except Exception as e:
        all_summaries.append({'object': obj_path, 'error': str(e)})

# Print summary output
for s in all_summaries:
    print('='*60)
    print('Object:', s.get('object'), '(SHA:', s.get('object_sha','?'),')')
    if 'error' in s:
        print('ERROR:', s['error'])
        continue
    print('Type:', s.get('type'))
    if s.get('info'):
        if s.get('type') == 'commit':
            print('Commit message:', s['info'])
        elif s.get('type') == 'blob':
            print('First 50 lines:' if s['info'] else '[Empty blob]')
            print(s['info'])
    if s.get('interest'):
        print('INTERESTING CONTEXT:')
        for part in s['interest']:
            print(part)
    print() 

print('==== Objects flagged as interesting ====')
for obj in interesting_objects:
    print(obj)
